    def _q2_deep_merge(self, target: Dict[str, Any], source: Dict[str, Any]) -> None:
        # q2-0204-tweaked (from QIDI 03.02): QIDI's Klipper sends only the changed nested
        # parts of multi_color_controller (BOX, drying); merge them in instead of replacing
        for key, value in source.items():
            if key in target and isinstance(target[key], dict) and isinstance(value, dict):
                self._q2_deep_merge(target[key], value)
            else:
                target[key] = copy.deepcopy(value)

